// Extended JCI master-data, sales, reports, account administration and recovery.
function module_scope_clause(string $alias, array &$args): string
{
    [$office, $region] = scope();
    if ($office !== null) { $args[] = $office; return " AND {$alias}.office_id=?"; }
    if ($region !== null) { $args[] = $region; return " AND {$alias}.region_id=?"; }
    return '';
}
function valid_iso_date(string $value): bool
{
    $date=DateTimeImmutable::createFromFormat('!Y-m-d',$value);
    return $date!==false&&$date->format('Y-m-d')===$value;
}

function master_validation_error(string $key, string $value, array $spec): ?string
{
    if (($spec['required'] ?? false) && $value === '') return $spec['label'].' is required.';
    if ($value === '') return null;
    if (preg_match('/[\x00-\x08\x0B\x0C\x0E-\x1F]/',$value)) return $spec['label'].' contains unsupported control characters.';
    $limits=['gst_rate'=>[0,28],'credit_limit'=>[0,999999999999.99],'credit_days'=>[0,3650]];
    $max = (int)($spec['maxlength'] ?? match($key) {
        'email'=>190,'name'=>180,'description'=>2000,'address'=>255,'state_name'=>100,'contact_person'=>120,
        'vendor_code','customer_code'=>30,'sku'=>40,'code'=>20,'gstin'=>15,'pan'=>10,'ifsc'=>11,'phone'=>25,'pincode'=>10,'hsn_code'=>12,'unit'=>20,'category'=>80,'msme_number'=>30,'bank_name'=>120,'bank_account'=>40,'credit_days'=>5,'credit_limit'=>14,
        default=>180
    });
    if (mb_strlen($value) > $max) return $spec['label'].' must be '.$max.' characters or fewer.';
    if (in_array($key,['email'],true) && !filter_var($value,FILTER_VALIDATE_EMAIL)) return 'Enter a valid email address.';
    if ($key==='pan' && !preg_match('/^[A-Z]{5}[0-9]{4}[A-Z]$/i',$value)) return 'PAN must use the format ABCDE1234F.';
    if ($key==='gstin' && !preg_match('/^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][A-Z0-9]Z[A-Z0-9]$/i',$value)) return 'GSTIN format is invalid.';
    if ($key==='ifsc' && !preg_match('/^[A-Z]{4}0[A-Z0-9]{6}$/i',$value)) return 'IFSC must use the format ABCD0123456.';
    if ($key==='pincode' && !preg_match('/^[1-9][0-9]{5}$/',$value)) return 'Enter a valid 6-digit Indian PIN code.';
    if ($key==='phone' && !preg_match('/^[+0-9() .-]{7,25}$/',$value)) return 'Enter a valid phone number.';
    if ($spec['type']==='number') {
        if (!is_numeric($value)) return $spec['label'].' must be a number.';
        $n=(float)$value;$min=(float)($spec['min']??$limits[$key][0]??0);$maxValue=(float)($spec['max']??$limits[$key][1]??999999999999.99);
        if ($n<$min||$n>$maxValue) return $spec['label']." must be between {$min} and {$maxValue}.";
        $step=(string)($spec['step']??'');if($step==='1'&&floor($n)!==$n)return $spec['label'].' must be a whole number.';
    }
    if (in_array($key,['code','vendor_code','customer_code','sku'],true) && !preg_match('/^[A-Za-z0-9][A-Za-z0-9._-]*$/',$value)) return $spec['label'].' may contain letters, numbers, dots, underscores and hyphens.';
    return null;
}

