            $quantities=[1,2,3,1,2];$prices=[500,120,80,350,900];
            for($i=0;$i<5;$i++){$qty=$quantities[$i];$price=$prices[$i];$rate=$productRows[$i][5];$taxable=round($qty*$price,2);$tax=round($taxable*$rate/100,2);$sale->execute(['JCI-UAT-'.date('Ymd').'-'.str_pad((string)($i+1),2,'0',STR_PAD_LEFT),$officeId,$customers[$i%count($customers)],$productIds[$i],$userId,$qty,$price,$rate,$taxable,$tax,$taxable+$tax]);$pdo->prepare('UPDATE product_stock SET quantity=quantity-? WHERE product_id=? AND office_id=?')->execute([$qty,$productIds[$i],$officeId]);}
