}

function master_page(string $kind, array $def): never
{
    global $pdo;
    $table=$def['table']; $fields=$def['fields']; $id=isset($_GET['edit'])?(int)$_GET['edit']:0;
    if ($_SERVER['REQUEST_METHOD']==='POST') {
        role(...$def['roles']); verify_csrf();
        $data=[];
        foreach($fields as $key=>$spec) {
            if($key==='active'||$key==='is_active') $data[$key]=isset($_POST[$key])?1:0;
            else $data[$key]=trim((string)($_POST[$key]??''));
            $validationError=master_validation_error($key,(string)$data[$key],$spec);
            if($validationError){flash($validationError,'error');go($kind.($id?'?edit='.$id:''));}
            if($data[$key]==='') $data[$key]=null;
        }
        if(isset($data['office_id'])&&!can('ADMIN','HO_MANAGER'))$data['office_id']=(int)user()['office_id'];
        if(in_array($kind,['vendors','customers'],true)&&!can('ADMIN','HO_MANAGER')){$check=$id?$pdo->prepare("SELECT active FROM `{$table}` WHERE id=?"):null;if($check){$check->execute([$id]);$data['active']=(int)$check->fetchColumn();}else $data['active']=0;}
        if($kind==='vendors') {
            if(!empty($data['blacklisted']))$data['active']=0;
        }
        try {
            if($id) {
                $set=implode(',',array_map(fn($c)=>"`{$c}`=?",array_keys($data)));
                $q=$pdo->prepare("UPDATE `{$table}` SET {$set} WHERE id=?");$q->execute([...array_values($data),$id]);
                audit($pdo,'update',$kind,$id,$data); flash($def['singular'].' updated.');
            } else {
                $cols=implode(',',array_map(fn($c)=>"`{$c}`",array_keys($data)));$marks=implode(',',array_fill(0,count($data),'?'));
                $q=$pdo->prepare("INSERT INTO `{$table}` ({$cols}) VALUES ({$marks})");$q->execute(array_values($data));$new=(int)$pdo->lastInsertId();
                audit($pdo,'create',$kind,$new,$data);flash($def['singular'].' created.');
            }
            go($kind);
        } catch(Throwable $e) { error_log($e->getMessage());flash('Could not save this record. Check required fields and duplicate codes.','error');go($kind.($id?'?edit='.$id:'')); }
    }
    role(...$def['roles']);
    $record=[];
    if($id){$q=$pdo->prepare("SELECT * FROM `{$table}` WHERE id=?");$q->execute([$id]);$record=$q->fetch()?:[];if(!$record){flash('Record not found.','error');go($kind);}}
    $args=[];$sql="SELECT * FROM `{$table}` WHERE 1=1";
    if(isset($def['office_scope'])){$officeField=$def['office_scope'];[$office,$region]=scope();if($office!==null){$sql.=" AND (`{$officeField}`=? OR `{$officeField}` IS NULL)";$args[]=$office;}elseif($region!==null){$sql.=" AND (`{$officeField}`=? OR `{$officeField}` IN (SELECT id FROM offices WHERE region_id=?) OR `{$officeField}` IS NULL)";$args[]=$region;$args[]=$region;}}
    $sql.=' ORDER BY '.($def['order']??'id DESC');$q=$pdo->prepare($sql);$q->execute($args);$rows=$q->fetchAll();
    $officeRows=$pdo->query('SELECT id,code,name,type FROM offices WHERE is_active=1 ORDER BY name')->fetchAll();$canForm=can_access($kind,$id?'edit':'create');
    layout($def['title'],function()use($kind,$def,$fields,$record,$rows,$officeRows,$id,$canForm){
        ?><div class="master-layout"><?php if($canForm):?><div class="card formcard"><div class="section"><div><h3><?=$id?'Edit':'Add'?> <?=e(strtolower($def['singular']))?></h3><p>Master records are centrally maintained and changes are audited.</p></div></div><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf())?>">
        <?php foreach($fields as $key=>$spec):$value=$record[$key]??($spec['default']??'');if($spec['type']==='office'):$current=(string)($value??'');?><label><?=e($spec['label'])?><select name="<?=e($key)?>"><option value="">All offices</option><?php foreach($officeRows as $o):?><option value="<?=$o['id']?>" <?=$current===(string)$o['id']?'selected':''?>><?=e($o['code'].' · '.$o['name'])?></option><?php endforeach;?></select></label>
        <?php elseif($spec['type']==='select'):?><label><?=e($spec['label'])?><select name="<?=e($key)?>"><?php foreach($spec['options'] as $v=>$label):?><option value="<?=e($v)?>" <?=((string)$value===(string)$v)?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label>
        <?php elseif($spec['type']==='check'):?><label class="check"><input type="checkbox" name="<?=e($key)?>" value="1" <?=($id?(bool)$value:(bool)($spec['default']??false))?'checked':''?>> <?=e($spec['label'])?></label>
        <?php elseif($spec['type']==='textarea'):?><label class="wide"><?=e($spec['label'])?><textarea name="<?=e($key)?>" rows="3" maxlength="2000"><?=e($value)?></textarea></label>
        <?php else:?><label class="<?=($spec['wide']??false)?'wide':''?>"><?=e($spec['label'])?><input type="<?=e($spec['type'])?>" name="<?=e($key)?>" value="<?=e($value)?>" <?=($spec['required']??false)?'required':''?> maxlength="<?=e($spec['maxlength']??match($key){'email'=>190,'name'=>180,'address'=>255,'gstin'=>15,'pan'=>10,'ifsc'=>11,'phone'=>25,'pincode'=>10,'hsn_code'=>12,'sku'=>40,'vendor_code','customer_code'=>30,default=>180})?>" <?=isset($spec['min'])?'min="'.e($spec['min']).'"':''?> <?=isset($spec['max'])?'max="'.e($spec['max']).'"':''?> <?=isset($spec['pattern'])?'pattern="'.e($spec['pattern']).'"':''?> <?=isset($spec['step'])?'step="'.e($spec['step']).'"':''?>></label><?php endif;endforeach; ?>
        <div class="actions wide"><?php if($id):?><a href="<?=e(url($kind))?>">Cancel edit</a><?php endif;?><button class="btn">Save <?=e(strtolower($def['singular']))?></button></div></form></div><?php else:?><div class="card formcard"><p>Your role has read-only access to this master.</p></div><?php endif;?><div class="card"><div class="section"><div><h3><?=e($def['title'])?></h3><p><?=count($rows)?> records available</p></div></div><div class="scroll"><table><thead><tr><?php foreach($def['columns'] as $col=>$label):?><th><?=e(strtoupper($label))?></th><?php endforeach;?><?php if(can_access($kind,'edit')):?><th>EDIT</th><?php endif;?></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php foreach($def['columns'] as $col=>$label):?><td><?=e((string)($r[$col]??'—'))?></td><?php endforeach;?><?php if(can_access($kind,'edit')):?><td><a href="<?=e(url($kind.'?edit='.$r['id']))?>">Edit</a></td><?php endif;?></tr><?php endforeach;if(!$rows):?><tr><td colspan="<?=count($def['columns'])+(can_access($kind,'edit')?1:0)?>" class="empty">No records yet.</td></tr><?php endif;?></tbody></table></div></div></div><?php
    });exit;
}

