if($path==='users') {
    role('ADMIN');$id=(int)($_GET['edit']??0);
    if($method==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$roleId=(int)($_POST['role_id']??0);$officeId=(int)($_POST['office_id']??0);$pw=(string)($_POST['password']??'');
        if(strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||!$roleId||!$officeId||(!$id&&strlen($pw)<14)||($pw!==''&&strlen($pw)<14)){flash('Provide a name, valid email, role, office, and a 14+ character password for new accounts or password changes.','error');go('users'.($id?'?edit='.$id:''));}
        try{if($id){$q=$pdo->prepare('UPDATE users SET name=?,email=?,role_id=?,office_id=?,is_active=? WHERE id=?');$q->execute([$name,$email,$roleId,$officeId,isset($_POST['is_active'])?1:0,$id]);if($pw!=='')$pdo->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($pw,PASSWORD_DEFAULT),$id]);audit($pdo,'update','user',$id);flash('User account updated.');}
        else{$q=$pdo->prepare('INSERT INTO users(name,email,password_hash,role_id,office_id) VALUES(?,?,?,?,?)');$q->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT),$roleId,$officeId]);$id=(int)$pdo->lastInsertId();audit($pdo,'create','user',$id);flash('User account created.');}go('users');}catch(Throwable $e){error_log($e->getMessage());flash('Could not save the user. The email may already be in use.','error');go('users'.($id?'?edit='.$id:''));}}
