if($path==='sales'&&$method==='POST') {
    role('ADMIN','HO_MANAGER','RO_MANAGER','DPC_OFFICER','APPROVER','AUDITOR');verify_csrf();$customer=(int)($_POST['customer_id']??0);$product=(int)($_POST['product_id']??0);$qty=(float)($_POST['quantity']??0);$price=(float)($_POST['unit_price']??0);$date=$_POST['sale_date']??date('Y-m-d');
    if(!$customer||!$product||!is_numeric($_POST['quantity']??null)||!is_numeric($_POST['unit_price']??null)||$qty<=0||$qty>99999999999.999||$price<0||$price>999999999999.99||!valid_iso_date((string)$date)||$date>date('Y-m-d')){flash('Select a customer and product, enter a valid quantity and price, and use a valid sale date no later than today.','error');go('sales');}
    try{$pdo->beginTransaction();[$cOffice,$cRegion]=scope();$customerSql='SELECT id FROM customers WHERE id=? AND active=1';$customerArgs=[$customer];if($cOffice!==null){$customerSql.=' AND (office_id IS NULL OR office_id=?)';$customerArgs[]=$cOffice;}elseif($cRegion!==null){$customerSql.=' AND (office_id IS NULL OR office_id=? OR office_id IN (SELECT id FROM offices WHERE region_id=?))';$customerArgs[]=$cRegion;$customerArgs[]=$cRegion;}$q=$pdo->prepare($customerSql);$q->execute($customerArgs);if(!$q->fetchColumn())throw new RuntimeException('Customer is not active or outside your permitted scope.');$q=$pdo->prepare('SELECT gst_rate FROM products WHERE id=? AND active=1');$q->execute([$product]);$rate=$q->fetchColumn();if($rate===false)throw new RuntimeException('Product is unavailable.');$q=$pdo->prepare('SELECT quantity FROM product_stock WHERE product_id=? AND office_id=? FOR UPDATE');$q->execute([$product,user()['office_id']]);$onHand=$q->fetchColumn();if($onHand===false||(float)$onHand<$qty)throw new RuntimeException('Insufficient stock at your office. Update stock before recording the sale.');
      $taxable=round($qty*$price,2);$tax=round($taxable*(float)$rate/100,2);$total=$taxable+$tax;$inv='JCI-SO-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(3)));
      $q=$pdo->prepare("INSERT INTO sales_orders(invoice_no,office_id,customer_id,product_id,created_by,quantity,unit_price,gst_rate,taxable_amount,tax_amount,total_amount,status,sale_date) VALUES(?,?,?,?,?,?,?,?,?,?,?,'confirmed',?)");$q->execute([$inv,user()['office_id'],$customer,$product,user()['id'],$qty,$price,$rate,$taxable,$tax,$total,$date]);$saleId=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE product_stock SET quantity=quantity-? WHERE product_id=? AND office_id=?')->execute([$qty,$product,user()['office_id']]);audit($pdo,'sale_create','sales_order',$saleId,['invoice'=>$inv,'total'=>$total]);$pdo->commit();flash('Sale recorded. Invoice reference '.$inv);go('invoice?id='.$saleId);
    }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e instanceof RuntimeException?$e->getMessage():'Could not record sale. Check customer and product records.','error');}go('sales');
}
