    if($type==='sales'){$sql='SELECT s.invoice_no reference,s.sale_date record_date,c.name party,p.name item,s.quantity,s.taxable_amount,s.tax_amount,s.total_amount,o.name office_name FROM sales_orders s JOIN customers c ON c.id=s.customer_id JOIN products p ON p.id=s.product_id JOIN offices o ON o.id=s.office_id WHERE s.sale_date BETWEEN ? AND ?';$args=[$from,$to];$scopeAlias='s.office_id';}
    elseif($type==='procurement'){$sql='SELECT CONCAT("JDP-PR-",LPAD(r.id,5,"0")) reference,DATE(r.created_at) record_date,u.name party,r.title item,r.quantity,r.estimated_amount taxable_amount,0 tax_amount,r.estimated_amount total_amount,o.name office_name FROM requisitions r JOIN users u ON u.id=r.created_by JOIN offices o ON o.id=r.office_id WHERE DATE(r.created_at) BETWEEN ? AND ?';$args=[$from,$to];$scopeAlias='r.office_id';}
    else{$sql='SELECT p.sku reference,DATE(s.updated_at) record_date,o.name party,p.name item,s.quantity,0 taxable_amount,0 tax_amount,0 total_amount,o.name office_name FROM product_stock s JOIN products p ON p.id=s.product_id JOIN offices o ON o.id=s.office_id WHERE DATE(s.updated_at) BETWEEN ? AND ?';$args=[$from,$to];$scopeAlias='s.office_id';}
    if($office!==null){$sql.=" AND {$scopeAlias}=?";$args[]=$office;}elseif($region!==null){$sql.=" AND ({$scopeAlias}=? OR o.region_id=?)";$args[]=$region;$args[]=$region;}elseif($selectedOffice>0){$sql.=" AND {$scopeAlias}=?";$args[]=$selectedOffice;}
    $q=$pdo->prepare($sql.' ORDER BY record_date DESC');$q->execute($args);$rows=$q->fetchAll();
    if(($_GET['format']??'')==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="jci-'.$type.'-report.csv"');$fp=fopen('php://output','w');if($rows){fputcsv($fp,array_keys($rows[0]));foreach($rows as $r)fputcsv($fp,$r);}fclose($fp);exit;}
    $officeRows=$office===null&&$region===null?$pdo->query('SELECT id,name FROM offices WHERE is_active=1 ORDER BY name')->fetchAll():[];layout('Reports',function()use($rows,$type,$from,$to,$selectedOffice,$officeRows){?><div class="card formcard reportform"><h3>Build operational report</h3><form method="get"><label>Report type<select name="type"><option value="sales" <?=$type==='sales'?'selected':''?>>Sales register</option><option value="procurement" <?=$type==='procurement'?'selected':''?>>Procurement requests</option><option value="inventory" <?=$type==='inventory'?'selected':''?>>Current stock balances</option></select></label><label>From<input type="date" name="from" value="<?=e($from)?>"></label><label>To<input type="date" name="to" value="<?=e($to)?>"></label><?php if($officeRows):?><label>Office<select name="office_id"><option value="0">All offices</option><?php foreach($officeRows as $o):?><option value="<?=$o['id']?>" <?=$selectedOffice===(int)$o['id']?'selected':''?>><?=e($o['name'])?></option><?php endforeach;?></select></label><?php endif;?><div class="actions"><button class="btn">Apply filters</button><a class="btn" href="<?=e(url('reports?type='.$type.'&from='.$from.'&to='.$to.'&office_id='.$selectedOffice.'&format=csv'))?>">Export CSV</a></div></form></div><div class="card reportresult"><div class="section"><div><h3><?=count($rows)?> report rows</h3><p>Filtered to your permitted organization scope</p></div></div><div class="scroll"><table><thead><tr><?php if($rows)foreach(array_keys($rows[0]) as $col):?><th><?=e(strtoupper(str_replace('_',' ',$col)))?></th><?php endforeach;?></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php foreach($r as $v):?><td><?=e($v)?></td><?php endforeach;?></tr><?php endforeach;if(!$rows):?><tr><td class="empty">No records match these filters.</td></tr><?php endif;?></tbody></table></div></div><?php });exit;
}

if($path==='forgot-password'&&$method==='POST') {
    verify_csrf();$email=strtolower(trim($_POST['email']??''));$q=$pdo->prepare('SELECT id,email,name FROM users WHERE email=? AND is_active=1');$q->execute([$email]);$u=$q->fetch();$message='If this account exists, a password reset link will be sent to its registered email.';
    if($u){$token=bin2hex(random_bytes(32));$pdo->prepare('INSERT INTO password_resets(user_id,token_hash,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 30 MINUTE))')->execute([$u['id'],hash('sha256',$token)]);$link=url('reset-password').'?token='.$token;$sent=mail($u['email'],'JCI JDP password reset',"Hello {$u['name']},\n\nUse this one-time link within 30 minutes to reset your password:\n{$link}\n");if(!$sent)error_log('JCI JDP password reset mail was not sent; configure PHP mail/SMTP.');}
    flash($message);go('forgot-password');
}
if($path==='forgot-password'){layout('Forgot password',function(){?><div class="login"><div class="eyebrow">ACCOUNT RECOVERY</div><h1>Reset your password</h1><p>We will email a one-time reset link to the account address.</p><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><label>Work email<input name="email" type="email" required></label><button class="btn">Send reset link</button></form><a href="<?=e(url('login'))?>">Back to sign in</a></div><?php });exit;}
if($path==='reset-password'&&$method==='POST') {
    verify_csrf();$token=(string)($_POST['token']??'');$pw=(string)($_POST['password']??'');if(strlen($pw)<14){flash('Choose a password of at least 14 characters.','error');go('reset-password?token='.urlencode($token));}$q=$pdo->prepare('SELECT id,user_id FROM password_resets WHERE token_hash=? AND used_at IS NULL AND expires_at>NOW()');$q->execute([hash('sha256',$token)]);$r=$q->fetch();if(!$r){flash('This reset link is invalid or expired. Request a new one.','error');go('forgot-password');}$pdo->beginTransaction();$pdo->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($pw,PASSWORD_DEFAULT),$r['user_id']]);$pdo->prepare('UPDATE password_resets SET used_at=NOW() WHERE user_id=? AND used_at IS NULL')->execute([$r['user_id']]);audit($pdo,'password_reset','user',(int)$r['user_id']);$pdo->commit();flash('Password reset. Sign in with your new password.');go('login');
}
if($path==='reset-password'){ $token=(string)($_GET['token']??'');$q=$pdo->prepare('SELECT id FROM password_resets WHERE token_hash=? AND used_at IS NULL AND expires_at>NOW()');$q->execute([hash('sha256',$token)]);if(!$q->fetchColumn()){flash('This reset link is invalid or expired. Request a new one.','error');go('forgot-password');}layout('Choose a new password',function()use($token){?><div class="login"><h1>Choose a new password</h1><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="token" value="<?=e($token)?>"><label>New password (14 characters minimum)<input type="password" name="password" minlength="14" required></label><button class="btn">Update password</button></form></div><?php });exit;}

if($path==='audit'){role('ADMIN','AUDITOR');$rows=$pdo->query('SELECT a.*,u.name user_name,o.name office_name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id LEFT JOIN offices o ON o.id=a.office_id ORDER BY a.created_at DESC LIMIT 300')->fetchAll();layout('Audit trail',function()use($rows){?><div class="card"><div class="section"><div><h3>Recent activity</h3><p>Latest recorded changes and access events</p></div></div><div class="scroll"><table><tr><th>TIME</th><th>USER</th><th>ACTION</th><th>RECORD</th><th>OFFICE</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['user_name']??'System')?></td><td><?=e(strtoupper($r['action']))?></td><td><?=e($r['entity_type'])?> #<?=e($r['entity_id'])?></td><td><?=e($r['office_name']??'—')?></td></tr><?php endforeach;?></table></div></div><?php });exit;}
